/** Promotion calculator operating entirely in integer cents. */
function validTier(tier) {
  return tier !== null
    && typeof tier === 'object'
    && !Array.isArray(tier)
    && Number.isInteger(tier.minimumCents)
    && tier.minimumCents >= 0
    && Number.isFinite(tier.percent)
    && tier.percent >= 0
    && tier.percent <= 100;
}

export function applyTieredDiscount(subtotalCents, tiers) {
  if (
    !Number.isInteger(subtotalCents)
    || subtotalCents < 0
    || !Array.isArray(tiers)
    || tiers.some(tier => !validTier(tier))
  ) {
    throw new TypeError('invalid discount input');
  }

  let selected;
  for (const tier of tiers) {
    if (
      tier.minimumCents <= subtotalCents
      && (!selected || tier.minimumCents > selected.minimumCents)
    ) {
      selected = tier;
    }
  }

  const percent = selected?.percent ?? 0;
  const discountCents = Math.round(subtotalCents * percent / 100);
  return { percent, discountCents, finalCents: subtotalCents - discountCents };
}
